/** An own icon on lucide's 24 px grid with its stroke, so both sets look alike. */
const svg = (children) => function OwnIcon({ size = 24, className, ...rest }) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2}
      strokeLinecap="round" strokeLinejoin="round" className={className} aria-hidden="true" {...rest}>{children}</svg>
  );
};

// Border edges of a 16 px box: the Borders gallery shows the box dotted and the edges it sets solid.
const EDGE = {
  top: <line key="t" x1="4" y1="4" x2="20" y2="4" />, bottom: <line key="b" x1="4" y1="20" x2="20" y2="20" />,
  left: <line key="l" x1="4" y1="4" x2="4" y2="20" />, right: <line key="r" x1="20" y1="4" x2="20" y2="20" />,
  h: <line key="h" x1="4" y1="12" x2="20" y2="12" />, v: <line key="v" x1="12" y1="4" x2="12" y2="20" />,
  down: <line key="d" x1="4" y1="4" x2="20" y2="20" />, up: <line key="u" x1="4" y1="20" x2="20" y2="4" />,
};
const OUTSIDE = ['top', 'bottom', 'left', 'right'];
const border = (...edges) => svg(<>
  <g strokeOpacity={0.4} strokeDasharray="1 3">{[...OUTSIDE, 'h', 'v'].map((k) => EDGE[k])}</g>
  {edges.map((k) => EDGE[k])}
</>);

// Table cell alignment: two lines of text placed in a cell box.
const ROW = { top: 7, center: 10, bottom: 13 };
const cell = (v, h) => {
  const x = (len) => ({ left: [6, 6 + len], center: [12 - len / 2, 12 + len / 2], right: [18 - len, 18] }[h]);
  const [a1, b1] = x(10);
  const [a2, b2] = x(6);
  return svg(<>
    <rect x="3" y="3" width="18" height="18" rx="2" strokeOpacity={0.4} />
    <line x1={a1} y1={ROW[v]} x2={b1} y2={ROW[v]} />
    <line x1={a2} y1={ROW[v] + 4} x2={b2} y2={ROW[v] + 4} />
  </>);
};

export const OWN = {
  borderBottom: border('bottom'), borderTop: border('top'), borderLeft: border('left'), borderRight: border('right'), borderNone: border(),
  borderAll: border(...OUTSIDE, 'h', 'v'), borderOutside: border(...OUTSIDE), borderInside: border('h', 'v'), borderInsideH: border('h'),
  borderInsideV: border('v'), borderDiagonalDown: border('down'), borderDiagonalUp: border('up'),
  cellTopLeft: cell('top', 'left'), cellTopCenter: cell('top', 'center'), cellTopRight: cell('top', 'right'),
  cellCenterLeft: cell('center', 'left'), cellCenter: cell('center', 'center'), cellCenterRight: cell('center', 'right'),
  cellBottomLeft: cell('bottom', 'left'), cellBottomCenter: cell('bottom', 'center'), cellBottomRight: cell('bottom', 'right'),
  // Distributed: every line runs the full width, the last one spread out too.
  alignDistributed: svg(<><path d="M3 6h18M3 12h18" /><path d="M3 18h18" strokeDasharray="3 4.5" /></>),
  // A large first letter beside the first lines of text.
  dropCap: svg(<><path d="M3 15 6.5 4 10 15M4.2 11.5h4.6" /><path d="M13 5h8M13 10h8M3 19h18" /></>),
  // Text above a short separator and the note under it, with its reference mark.
  footnote: svg(<><path d="M3 5h13M3 9h18" /><path d="M3 15h6M3 19h12" /><path d="M20 3v4" /></>),
  // The note at the end, after the last text.
  endnote: svg(<><path d="M3 5h18M3 9h18M3 13h12" /><path d="M3 19h6" /><path d="M14 17v4" /></>),
  integral: svg(<path d="M16 4c-2 0-3 1-3 3v10c0 2-1 3-3 3" />),
  // A circumflex over a dotted box: an accent over any letter.
  accent: svg(<><path d="m8 7 4-4 4 4" /><rect x="7" y="10" width="10" height="11" rx="1" strokeDasharray="2 2" /></>),
  // A letter beside an arrow pointing down: text turned to run downwards.
  textDirection: svg(<><path d="M3 17 7 6l4 11M4.5 13h5" /><path d="M18 4v15M15 16l3 3 3-3" /></>),
};

/** The icon component for a spec icon `name` (a lucide name or 'own:<name>'), or null. */
export const iconOf = (name) => (name?.startsWith('own:') ? OWN[name.slice(4)] : LUCIDE[name]) ?? null;

/** Draws the spec icon `name`; nothing when the name is unknown. */
export function RibbonIcon({ name, ...props }) {
  const I = iconOf(name);
  return I ? <I {...props} /> : null;
}
